    Always.winning | Full Rage Build
    Silent + Melee  = Sleepy/Meow path
    Orbit           = Lua x / MeowwCL
    Fake Position   = Sleepy underground desync
    Body Split      = Lua x riot / offset stick
    Void Spam       = MeowwCL patterns
]]

if getgenv().AlwaysWinning and getgenv().AlwaysWinning.Unload then
    pcall(getgenv().AlwaysWinning.Unload)
end

local Players = game:GetService("Players")
local RunService = game:GetService("RunService")
local Workspace = game:GetService("Workspace")
local UserInputService = game:GetService("UserInputService")
local HttpService = game:GetService("HttpService")
local TweenService = game:GetService("TweenService")

local LocalPlayer = Players.LocalPlayer
local Camera = Workspace.CurrentCamera
local cloneref = cloneref or function(x) return x end

getgenv().meow_flags = getgenv().meow_flags or {}
local flags = getgenv().meow_flags

-- defaults
flags.silent_aim_enabled = true
flags.hit_chance = flags.hit_chance or 100
flags.fov_radius_smoothed = flags.fov_radius_smoothed or 400
flags.target_priority = flags.target_priority or "Closest"
flags.target_hitbox = flags.target_hitbox or "Head"
flags.knife_rage = true
flags.melee_safe_reach = flags.melee_safe_reach or 12
flags.melee_auto_face_back = true
flags.riot_shield_check = false
flags.avoid_katana_deflect = false
flags.show_fov = true
flags.orbit = false
flags.orbitSpeed = 90
flags.orbitDistance = 8
flags.orbitHeight = 0
flags.orbitSource = "LuaX" -- LuaX | MeowwCL
flags.fakePositionEnabled = false
flags.fake_position_depth = 5.8
flags.voidSpamEnabled = false
flags.voidPattern = "random"
flags.voidSpamInterval = 0.016
flags.voidSpamBurst = 5
flags.voidXPos, flags.voidXNeg = 2500, 2500
flags.voidYPos, flags.voidYNeg = 1500, 1500
flags.voidZPos, flags.voidZNeg = 2500, 2500
flags.voidAxisX, flags.voidAxisY, flags.voidAxisZ = true, true, true
flags.voidSmooth = false
flags.voidSmoothAlpha = 0.5
flags.bodySplitEnabled = false
flags.bodySplitMode = "Stick" -- Stick | Bounce
flags.bodySplitHeight = 3
flags.bodySplitForward = 0
flags.bodySplitRight = 0
flags.daggerBypass = true
flags.module = "Sleepy"

getgenv().meowState = getgenv().meowState or {
    Destroyed = false,
    PriorityList = {},
    CurrentTarget = nil,
    LastTargetPlayer = nil,
    LastMeleeAttack = 0,
}
local meowState = getgenv().meowState
meowState.Destroyed = false

local fakePos = {
    Enabled = false,
    Depth = 5.8,
    WalkMode = true,
    SurfaceCamera = true,
    AutoNoclip = true,
    HideMeshes = true,
    ZeroVelocity = true,
    VirtualCF = nil,
    OriginalParts = nil,
    ClientCF = nil,
    FakeCF = nil,
}

local conns = {}
local function track(c) conns[#conns+1] = c; return c end

local function getHrp()
    local c = LocalPlayer.Character
    return c and c:FindFirstChild("HumanoidRootPart")
end

local function getClosest()
    local hrp = getHrp()
    if not hrp then return nil end
    local best, bestD = nil, math.huge
    for _, p in ipairs(Players:GetPlayers()) do
        if p ~= LocalPlayer and p.Character then
            local r = p.Character:FindFirstChild("HumanoidRootPart")
            local h = p.Character:FindFirstChildOfClass("Humanoid")
            if r and h and h.Health > 0 then
                local d = (hrp.Position - r.Position).Magnitude
                if d < bestD then bestD, best = d, p end
            end
        end
    end
    return best
end

-- ========== SLEEPY HELPERS + TARGET + SILENT ==========
silent_closest_hitbox = function(char)
    if not char then return nil end
    local mode = flags.target_hitbox or "Head"
    if mode == "Head" then
        return char:FindFirstChild("Head") or char:FindFirstChild("HumanoidRootPart")
    elseif mode == "HumanoidRootPart" or mode == "Torso" then
        return char:FindFirstChild("HumanoidRootPart") or char:FindFirstChild("Torso") or char:FindFirstChild("UpperTorso")
    elseif mode == "Random" then
        local parts = {"Head", "HumanoidRootPart", "UpperTorso", "LowerTorso"}
        return char:FindFirstChild(parts[math.random(1, #parts)]) or char:FindFirstChild("HumanoidRootPart")
    end
    return char:FindFirstChild("Head") or char:FindFirstChild("HumanoidRootPart")
end
is_deflecting = function(fighter)
    if not fighter then return false end
    local char = (type(fighter) == "table" and fighter.Character) or (typeof(fighter) == "Instance" and fighter)
    if not char then return false end
    local katana = char:FindFirstChild("Katana")
    if katana and katana:FindFirstChild("Deflecting") and katana.Deflecting.Value == true then
        return true
    end
    return false
end

shield_blocks_shot = function(targetRoot, shooterPos)
    if not targetRoot then return false end
    local char = targetRoot.Parent
    if not char then return false end
    local shield = char:FindFirstChild("Riot Shield") or char:FindFirstChild("Shield")
    if not shield then return false end
    local targetLook = targetRoot.CFrame.LookVector
    local shotDir = (shooterPos - targetRoot.Position).Unit
    return targetLook:Dot(shotDir) < -0.2
end

ragebot_is_priority = function(player)
    if not player then return false end
    local name = typeof(player) == "Instance" and player.Name or tostring(player)
    return meowState.PriorityList[name:lower()] == true
end

ragebot_add_priority = function(player)
    if not player then return end
    local name = typeof(player) == "Instance" and player.Name or tostring(player)
    meowState.PriorityList[name:lower()] = true
end
getgenv()._Meow_AddPriority = ragebot_add_priority

silent_closest_hitbox = function(char)
    if not char then return nil end
    local mode = flags.target_hitbox or "Head"
    if mode == "Head" then
        return char:FindFirstChild("Head") or char:FindFirstChild("HumanoidRootPart")
    elseif mode == "HumanoidRootPart" or mode == "Torso" then
        return char:FindFirstChild("HumanoidRootPart") or char:FindFirstChild("Torso") or char:FindFirstChild("UpperTorso")
    elseif mode == "Random" then
        local parts = {"Head", "HumanoidRootPart", "UpperTorso", "LowerTorso"}
        return char:FindFirstChild(parts[math.random(1, #parts)]) or char:FindFirstChild("HumanoidRootPart")
    end
    return char:FindFirstChild("Head") or char:FindFirstChild("HumanoidRootPart")
end
silent_closest_part = silent_closest_hitbox
targeting_silent_part = silent_closest_hitbox
target_aim_part = silent_closest_hitbox
random_hitpart_name = function()
    local p = {"Head", "HumanoidRootPart", "Torso", "UpperTorso"}
    return p[math.random(1, #p)]
end

get_target = function()
    local myChar = LocalPlayer.Character
    if not myChar then return nil end
    local myRoot = myChar:FindFirstChild("HumanoidRootPart")
    if not myRoot then return nil end

    local bestTarget = nil
    local bestScore = math.huge
    local method = flags.target_priority or "Lowest Health"
    local fovRadius = flags.fov_radius_smoothed or 120
    local center = Camera.ViewportSize / 2

    for _, pl in ipairs(Players:GetPlayers()) do
        if pl ~= LocalPlayer and pl.Character then
            local char = pl.Character
            local hum = char:FindFirstChildOfClass("Humanoid")
            local root = char:FindFirstChild("HumanoidRootPart")

            if hum and hum.Health > 0 and root and not char:FindFirstChildOfClass("ForceField") then
                if not (flags.riot_shield_check and shield_blocks_shot(root, myRoot.Position)) then
                    if not (flags.avoid_katana and is_deflecting(char)) then
                        local scrPos, onScreen = Camera:WorldToViewportPoint(root.Position)
                        local fovDist = (Vector2.new(scrPos.X, scrPos.Y) - center).Magnitude

                        if not flags.silent_aim_enabled or fovDist <= fovRadius then
                            local dist = (root.Position - myRoot.Position).Magnitude
                            local health = hum.Health
                            local isPriority = ragebot_is_priority(pl)
                            local score = health

                            if method == "Distance" or method == "Closest Distance" then
                                score = dist
                            elseif method == "Crosshair" then
                                score = fovDist
                            elseif method == "FOV - Lowest Health" then
                                score = (health * 2) + fovDist
                            else
                                score = health
                            end

                            if isPriority then
                                score = score - 10000
                            end

                            if score < bestScore then
                                bestScore = score
                                bestTarget = {
                                    Player = pl,
                                    Character = char,
                                    Humanoid = hum,
                                    RootPart = root,
                                    HitPart = silent_closest_hitbox(char),
                                    Distance = dist,
                                    FOVDistance = fovDist,
                                }
                            end
                        end
                    end
                end
            end
        end
    end

    meowState.CurrentTarget = bestTarget
    if bestTarget then meowState.LastTargetPlayer = bestTarget.Player end
    return bestTarget
end
local function runMeleeAura()
    if not flags.knife_rage then return end
    local myChar = LocalPlayer.Character
    local myRoot = myChar and myChar:FindFirstChild("HumanoidRootPart")
    if not myRoot then return end
    local now = os.clock()
    if now - (meowState.LastMeleeAttack or 0) < 0.12 then return end
    local reach = flags.melee_safe_reach or 12
    for _, pl in ipairs(Players:GetPlayers()) do
        if pl ~= LocalPlayer and pl.Character then
            local root = pl.Character:FindFirstChild("HumanoidRootPart")
            local hum = pl.Character:FindFirstChildOfClass("Humanoid")
            if root and hum and hum.Health > 0 then
                if (root.Position - myRoot.Position).Magnitude <= reach then
                    meowState.LastMeleeAttack = now
                    pcall(function()
                        if flags.melee_auto_face_back ~= false then
                            myRoot.CFrame = CFrame.new(myRoot.Position, myRoot.Position - root.CFrame.LookVector)
                        end
                        local tool = myChar:FindFirstChildOfClass("Tool")
                        if tool then tool:Activate() end
                    end)
                    break
                end
            end
        end
    end
end


-- ========== SILENT NAMECALL ==========
if type(hookmetamethod) == "function" and type(getnamecallmethod) == "function" then
    local oldNamecall
    oldNamecall = hookmetamethod(game, "__namecall", function(self, ...)
        local method = getnamecallmethod()
        local args = {...}
        if (not checkcaller or not checkcaller()) and flags.silent_aim_enabled then
            if (method == "Raycast" or method == "FindPartOnRayWithIgnoreList" or method == "FindPartOnRay") and self == Workspace then
                local origin = args[1]
                if fakePos.Enabled and fakePos.VirtualCF then
                    origin = fakePos.VirtualCF.Position
                    args[1] = origin
                end
                local target = meowState.CurrentTarget or get_target()
                if target and target.HitPart then
                    if math.random(1, 100) <= (flags.hit_chance or 100) then
                        args[2] = (target.HitPart.Position - origin).Unit * 1000
                        return oldNamecall(self, table.unpack(args))
                    end
                end
            end
        end
        return oldNamecall(self, ...)
    end)
end

-- dagger bypass (MeowwCL)
pcall(function()
    if type(hookfunction) ~= "function" then return end
    local oldFire
    oldFire = hookfunction(Instance.new("RemoteEvent").FireServer, newcclosure and newcclosure(function(self, ...)
        if (not checkcaller or not checkcaller()) and flags.daggerBypass then
            local n = tostring(self.Name):lower()
            local a = table.concat({...}, " "):lower()
            if (n:find("dagger") or n:find("knife") or n:find("throw") or n:find("blade"))
                and not (a:find(LocalPlayer.Name:lower()) or a:find("owner")) then
                return
            end
        end
        return oldFire(self, ...)
    end) or function(self, ...)
        if flags.daggerBypass then
            local n = tostring(self.Name):lower()
            if n:find("dagger") or n:find("knife") then return end
        end
        return oldFire(self, ...)
    end)
end)

-- ========== SLEEPY FAKE POSITION ==========
local function undergroundCapture()
    local char = LocalPlayer.Character
    if not char then return end
    fakePos.OriginalParts = {}
    for _, part in ipairs(char:GetDescendants()) do
        if part:IsA("BasePart") or part:IsA("Decal") then
            table.insert(fakePos.OriginalParts, { part = part, transparency = part.Transparency })
            if fakePos.HideMeshes then pcall(function() part.Transparency = 1 end) end
        end
    end
end

local function undergroundRestore()
    if not fakePos.OriginalParts then return end
    for _, data in ipairs(fakePos.OriginalParts) do
        if data.part and data.part.Parent then
            pcall(function() data.part.Transparency = data.transparency end)
        end
    end
    fakePos.OriginalParts = nil
end

local function setFakePosition(state)
    if fakePos.Enabled == state then return end
    fakePos.Enabled = state
    flags.fakePositionEnabled = state
    local hrp = getHrp()
    if state then
        if hrp then fakePos.VirtualCF = hrp.CFrame end
        if fakePos.HideMeshes then undergroundCapture() end
        pcall(function()
            RunService:UnbindFromRenderStep("AW_FakePosCam")
            RunService:BindToRenderStep("AW_FakePosCam", 201, function()
                if fakePos.Enabled and fakePos.SurfaceCamera then
                    local cam = workspace.CurrentCamera
                    local depth = flags.fake_position_depth or fakePos.Depth
                    if cam and depth > 0 then cam.CFrame = cam.CFrame + Vector3.new(0, depth, 0) end
                end
            end)
        end)
    else
        pcall(function() RunService:UnbindFromRenderStep("AW_FakePosCam") end)
        undergroundRestore()
        if hrp and fakePos.VirtualCF then
            pcall(function()
                if fakePos.ZeroVelocity then
                    hrp.AssemblyLinearVelocity = Vector3.zero
                    hrp.AssemblyAngularVelocity = Vector3.zero
                end
                hrp.CFrame = fakePos.VirtualCF
            end)
        end
        fakePos.VirtualCF = nil
    end
end

track(RunService.Heartbeat:Connect(function(dt)
    if not fakePos.Enabled or meowState.Destroyed then return end
    local char = LocalPlayer.Character
    local hrp = char and char:FindFirstChild("HumanoidRootPart")
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    if not hrp or not hum then return end
    if not fakePos.VirtualCF then fakePos.VirtualCF = hrp.CFrame end
    local cam = Workspace.CurrentCamera
    local look = cam and cam.CFrame.LookVector or Vector3.new(0,0,-1)
    local yaw = math.atan2(-look.X, -look.Z)
    local surfaceRot = CFrame.Angles(0, yaw, 0)
    if fakePos.WalkMode then
        local md = hum.MoveDirection
        if md.Magnitude > 0 then
            fakePos.VirtualCF = CFrame.new(fakePos.VirtualCF.Position + md * (hum.WalkSpeed * dt)) * surfaceRot
        else
            fakePos.VirtualCF = CFrame.new(fakePos.VirtualCF.Position) * surfaceRot
        end
    end
    local depth = flags.fake_position_depth or fakePos.Depth
    local under = fakePos.VirtualCF.Position - Vector3.new(0, depth, 0)
    if fakePos.AutoNoclip then
        for _, p in ipairs(char:GetDescendants()) do
            if p:IsA("BasePart") and p.CanCollide then p.CanCollide = false end
        end
    end
    if fakePos.ZeroVelocity then
        hrp.AssemblyLinearVelocity = Vector3.zero
        hrp.AssemblyAngularVelocity = Vector3.zero
    end
    hrp.CFrame = CFrame.new(under) * surfaceRot
end))

-- ========== ORBIT (LuaX primary, MeowwCL style secondary) ==========
local orbAngle, orbConn = 0, nil
local function stopOrbit()
    if orbConn then orbConn:Disconnect(); orbConn = nil end
    flags.orbit = false
end
local function startOrbit()
    stopOrbit()
    flags.orbit = true
    local hum = LocalPlayer.Character and LocalPlayer.Character:FindFirstChildOfClass("Humanoid")
    if hum then pcall(function() hum:ChangeState(Enum.HumanoidStateType.Physics) end) end
    orbAngle = 0
    orbConn = track(RunService.Heartbeat:Connect(function(dt)
        if not flags.orbit or meowState.Destroyed then return end
        local my = getHrp()
        if not my then return end
        local cl = getClosest()
        if not cl or not cl.Character then return end
        local hrp = cl.Character:FindFirstChild("HumanoidRootPart")
        if not hrp then return end
        local speed = (flags.orbitSpeed or 90)
        local radius = flags.orbitDistance or 8
        local height = flags.orbitHeight or 0
        orbAngle = orbAngle + math.rad(speed) * dt
        local offset = Vector3.new(math.cos(orbAngle) * radius, height, math.sin(orbAngle) * radius)
        if flags.orbitSource == "MeowwCL" then
            my.CFrame = CFrame.new(hrp.Position + offset, hrp.Position)
        else
            -- LuaX style smooth face
            local dst = hrp.Position + offset
            my.CFrame = CFrame.new(my.Position:Lerp(dst, 0.35), Vector3.new(hrp.Position.X, my.Position.Y, hrp.Position.Z))
        end
        pcall(function()
            my.AssemblyLinearVelocity = Vector3.zero
            my.AssemblyAngularVelocity = Vector3.zero
        end)
    end))
end

-- ========== BODY SPLIT (Lua x riot abuse style) ==========
local bodyConn = nil
local function stopBodySplit()
    if bodyConn then bodyConn:Disconnect(); bodyConn = nil end
    flags.bodySplitEnabled = false
end
local function startBodySplit()
    stopBodySplit()
    flags.bodySplitEnabled = true
    bodyConn = track(RunService.Heartbeat:Connect(function()
        if not flags.bodySplitEnabled or meowState.Destroyed then return end
        local my = getHrp()
        if not my then return end
        local cl = getClosest()
        if not cl or not cl.Character then return end
        local tr = cl.Character:FindFirstChild("HumanoidRootPart")
        if not tr then return end
        local h = flags.bodySplitHeight or 3
        local f = flags.bodySplitForward or 0
        local r = flags.bodySplitRight or 0
        local mode = flags.bodySplitMode or "Stick"
        if mode == "Bounce" then
            local bounce = math.abs(math.sin(tick() * 8)) * math.abs(h)
            my.CFrame = CFrame.new(tr.Position + Vector3.new(r, bounce, f))
        else
            my.CFrame = CFrame.new(tr.Position + Vector3.new(r, h, f))
        end
        my.AssemblyLinearVelocity = Vector3.zero
    end))
end

-- ========== VOID SPAM (MeowwCL patterns) ==========
local voidSpamConn, voidSpiral, voidWave, voidHelix = nil, 0, 0, 0
local voidBounce = { X = 1, Y = 1, Z = 1 }
local voidChaos = { math.random(), math.random(), math.random() }

local function getVoidDelta(dt)
    local xp, xn = flags.voidXPos or 2500, flags.voidXNeg or 2500
    local yp, yn = flags.voidYPos or 1500, flags.voidYNeg or 1500
    local zp, zn = flags.voidZPos or 2500, flags.voidZNeg or 2500
    local ax, ay, az = flags.voidAxisX ~= false, flags.voidAxisY ~= false, flags.voidAxisZ ~= false
    local p = flags.voidPattern or "random"
    if p == "spiral" then
        voidSpiral = voidSpiral + 0.35
        return Vector3.new(ax and math.cos(voidSpiral)*(xp+xn)/2 or 0, ay and math.sin(voidSpiral*0.6)*(yp+yn)/2 or 0, az and math.sin(voidSpiral)*(zp+zn)/2 or 0)
    elseif p == "wave" then
        voidWave = voidWave + dt * 8
        return Vector3.new(ax and math.sin(voidWave)*(xp+xn)/2 or 0, ay and math.sin(voidWave*1.7)*(yp+yn)/2 or 0, az and math.cos(voidWave*0.9)*(zp+zn)/2 or 0)
    elseif p == "helix" then
        voidHelix = voidHelix + dt * 6
        return Vector3.new(ax and math.cos(voidHelix*2)*(xp+xn)/2 or 0, ay and math.sin(voidHelix)*(yp+yn)/8 or 0, az and math.sin(voidHelix*2)*(zp+zn)/2 or 0)
    elseif p == "bounce" then
        if math.random() < 0.25 then voidBounce.X = -voidBounce.X end
        if math.random() < 0.25 then voidBounce.Y = -voidBounce.Y end
        if math.random() < 0.25 then voidBounce.Z = -voidBounce.Z end
        return Vector3.new(ax and voidBounce.X*(xp+xn)/3 or 0, ay and voidBounce.Y*(yp+yn)/3 or 0, az and voidBounce.Z*(zp+zn)/3 or 0)
    else
        return Vector3.new(ax and (math.random()*(xp+xn)-xn) or 0, ay and (math.random()*(yp+yn)-yn) or 0, az and (math.random()*(zp+zn)-zn) or 0)
    end
end

local function stopVoidSpam()
    if voidSpamConn then voidSpamConn:Disconnect(); voidSpamConn = nil end
    flags.voidSpamEnabled = false
end
local function startVoidSpam()
    stopVoidSpam()
    flags.voidSpamEnabled = true
    local acc = 0
    voidSpamConn = track(RunService.Heartbeat:Connect(function(dt)
        if not flags.voidSpamEnabled or meowState.Destroyed then return end
        local root = getHrp()
        if not root then return end
        acc = acc + dt
        local interval = math.max(flags.voidSpamInterval or 0.016, 0.005)
        if acc < interval then return end
        acc = acc % interval
        local burst = math.clamp(flags.voidSpamBurst or 5, 1, 20)
        for _ = 1, burst do
            local delta = getVoidDelta(dt)
            local newPos = root.Position + delta
            if flags.voidSmooth then
                newPos = root.Position:Lerp(root.Position + delta, math.clamp(flags.voidSmoothAlpha or 0.5, 0.01, 1))
            end
            root.CFrame = CFrame.new(newPos, newPos + root.CFrame.LookVector)
        end
    end))
end

-- ========== MAIN COMBAT LOOP ==========
local fovCircle, fovOutline
track(RunService.Heartbeat:Connect(function()
    if meowState.Destroyed then return end
    pcall(function()
        meowState.CurrentTarget = get_target()
        if flags.knife_rage then runMeleeAura() end
    end)
end))

track(RunService.RenderStepped:Connect(function()
    if meowState.Destroyed or not Drawing then return end
    if not fovCircle then
        fovCircle = Drawing.new("Circle")
        fovCircle.Thickness = 1
        fovCircle.NumSides = 64
        fovCircle.Filled = false
        fovCircle.Color = Color3.new(1,1,1)
        fovOutline = Drawing.new("Circle")
        fovOutline.Thickness = 2
        fovOutline.NumSides = 64
        fovOutline.Color = Color3.new(0,0,0)
        fovOutline.Transparency = 0.5
    end
    local show = flags.show_fov and flags.silent_aim_enabled
    fovCircle.Visible = show
    if fovOutline then fovOutline.Visible = show end
    if show then
        local c = Camera.ViewportSize / 2
        local r = flags.fov_radius_smoothed or 400
        fovCircle.Position, fovCircle.Radius = c, r
        if fovOutline then fovOutline.Position, fovOutline.Radius = c, r end
    end
end))

-- ========== UI ==========
local function buildUI()
    local ok, Library = pcall(function()
        return loadstring(game:HttpGet("https://raw.githubusercontent.com/deividcomsono/Obsidian/main/Library.lua"))()
    end)
    if not ok or not Library then
        print("[Always.winning] UI skip — headless OK")
        return
    end
    local Window = Library:CreateWindow({
        Title = "Always.winning | PaidV2",
        Footer = "silent · melee · orbit · fakepos · void · body",
        Center = true,
        AutoShow = true,
        Resizable = true,
        MobileButtonsSide = "Right",
    })
    local Tabs = {
        Rage = Window:AddTab("Rage"),
        Move = Window:AddTab("Movement"),
        Void = Window:AddTab("Void"),
        Settings = Window:AddTab("Settings"),
    }

    local S = Tabs.Rage:AddLeftGroupbox("Silent Aim")
    S:AddToggle("Silent", { Text = "Silent Aim", Default = true, Callback = function(v) flags.silent_aim_enabled = v end })
    S:AddToggle("ShowFov", { Text = "Show FOV", Default = true, Callback = function(v) flags.show_fov = v end })
    S:AddSlider("Fov", { Text = "FOV", Default = 400, Min = 20, Max = 800, Rounding = 0, Callback = function(v) flags.fov_radius_smoothed = v end })
    S:AddSlider("HC", { Text = "Hit Chance", Default = 100, Min = 1, Max = 100, Rounding = 0, Callback = function(v) flags.hit_chance = v end })
    S:AddDropdown("Hitbox", { Text = "Hitbox", Default = "Head", Values = {"Head","HumanoidRootPart","Torso","Random"}, Callback = function(v) flags.target_hitbox = v end })
    S:AddDropdown("Prio", { Text = "Priority", Default = "Closest", Values = {"Closest","Lowest Health","Distance","Crosshair","FOV - Lowest Health"}, Callback = function(v) flags.target_priority = v end })

    local M = Tabs.Rage:AddRightGroupbox("Melee")
    M:AddToggle("Melee", { Text = "Melee Aura", Default = true, Callback = function(v) flags.knife_rage = v end })
    M:AddSlider("Reach", { Text = "Reach", Default = 12, Min = 4, Max = 30, Rounding = 0, Callback = function(v) flags.melee_safe_reach = v end })
    M:AddToggle("FaceBack", { Text = "Face Back", Default = true, Callback = function(v) flags.melee_auto_face_back = v end })
