        b.Font = Enum.Font.Gotham
        b.TextSize = 10
        b.Parent = modeRow
        Instance.new("UICorner", b).CornerRadius = UDim.new(0, 4)
        local s = Instance.new("UIStroke", b)
        s.Color = active and Color3.fromRGB(0, 162, 255) or Color3.fromRGB(28, 30, 40)
        s.Thickness = 1
        return b, s
